from unittest import TestCase

from piccolo.apps.migrations.auto.serialisation import serialise_params
from piccolo.columns.column_types import BigInt, ForeignKey, Integer, Varchar
from piccolo.columns.generated import Identity
from piccolo.table import Table
from piccolo.testing.test_case import TableTest
from tests.base import engines_only


class TestIdentity(TestCase):
    def test_postgres(self):
        self.assertEqual(Identity().postgres, "GENERATED ALWAYS AS IDENTITY")
        self.assertEqual(
            Identity(always=False).postgres,
            "GENERATED BY DEFAULT AS IDENTITY",
        )
        self.assertEqual(
            Identity(start=1000, increment=2).postgres,
            "GENERATED ALWAYS AS IDENTITY (START WITH 1000 INCREMENT BY 2)",
        )
        self.assertEqual(
            Identity(increment=-1).postgres,
            "GENERATED ALWAYS AS IDENTITY (INCREMENT BY -1)",
        )

    def test_cockroach(self):
        self.assertEqual(
            Identity(start=10).cockroach,
            "GENERATED ALWAYS AS IDENTITY (START WITH 10)",
        )

    def test_sqlite(self):
        self.assertEqual(Identity().sqlite, "")

    def test_validation(self):
        with self.assertRaises(ValueError):
            Identity(start="1")  # type: ignore

        with self.assertRaises(ValueError):
            Identity(increment=0)

    def test_writable(self):
        self.assertFalse(Identity().writable)
        self.assertTrue(Identity(always=False).writable)

    def test_repr(self):
        """
        Make sure it can be serialised in migration files.
        """
        self.assertEqual(
            repr(Identity(always=False, start=5)),
            "Identity(always=False, start=5, increment=None)",
        )

    def test_equality(self):
        self.assertEqual(Identity(), Identity())
        self.assertNotEqual(Identity(), Identity(always=False))


class BandIdentity(Table):
    id = BigInt(primary_key=True, generated=Identity())
    name = Varchar()


class ConcertIdentity(Table):
    band = ForeignKey(BandIdentity)


class TestIdentityPrimaryKey(TableTest):
    tables = [BandIdentity, ConcertIdentity]

    @engines_only("postgres", "cockroach")
    def test_ddl(self):
        self.assertEqual(
            BandIdentity.id.ddl,
            '"id" BIGINT PRIMARY KEY NOT NULL GENERATED ALWAYS AS IDENTITY',
        )

    @engines_only("sqlite")
    def test_ddl_sqlite(self):
        self.assertEqual(
            BandIdentity.id.ddl, '"id" INTEGER PRIMARY KEY NOT NULL'
        )

    def test_foreign_key(self):
        """
        The foreign key column shouldn't be an identity column.
        """
        self.assertNotIn("IDENTITY", ConcertIdentity.band.ddl)

    def test_insert(self):
        band = BandIdentity(name="Pythonistas")
        band.save().run_sync()
        self.assertIsInstance(band.id, int)

        band.name = "Rustaceans"
        band.save().run_sync()

        self.assertEqual(
            BandIdentity.select(BandIdentity.name).run_sync(),
            [{"name": "Rustaceans"}],
        )

    def test_default_not_allowed(self):
        with self.assertRaises(ValueError):
            Integer(default=1, generated=Identity())

    def test_no_default(self):
        """
        Generated columns shouldn't have a default, so it doesn't appear in
        migrations or ``piccolo schema generate`` output.
        """
        self.assertIsNone(BandIdentity.id.default)
        self.assertIsNone(BandIdentity.id._meta.params["default"])

    def test_serialisation(self):
        serialised = serialise_params(params=BandIdentity.id._meta.params)
        self.assertEqual(
            repr(serialised.params["generated"]),
            "Identity(always=True, start=None, increment=None)",
        )
        self.assertIn(
            "from piccolo.columns.generated import Identity",
            [repr(i) for i in serialised.extra_imports],
        )


class TicketIdentity(Table):
    """
    Identity columns which aren't primary keys - SQLite doesn't support these.
    """

    name = Varchar()
    serial_number = Integer(generated=Identity())
    ticket_number = Integer(generated=Identity(always=False, start=100))


@engines_only("postgres", "cockroach")
class TestIdentityNonPrimaryKey(TableTest):
    tables = [TicketIdentity]

    def test_ddl(self):
        self.assertEqual(
            TicketIdentity.ticket_number.ddl,
            '"ticket_number" INTEGER NOT NULL GENERATED BY DEFAULT AS '
            "IDENTITY (START WITH 100)",
        )

    def test_insert(self):
        TicketIdentity.insert(
            TicketIdentity(name="Front row"),
            TicketIdentity(name="Back row", ticket_number=5),
        ).run_sync()

        self.assertEqual(
            TicketIdentity.select(TicketIdentity.ticket_number)
            .order_by(TicketIdentity.id)
            .output(as_list=True)
            .run_sync(),
            [100, 5],
        )

    def test_save(self):
        """
        ``save`` shouldn't try writing to ``GENERATED ALWAYS`` columns, as the
        database rejects it.
        """
        TicketIdentity(name="Front row").save().run_sync()

        # Load it from the database, so `serial_number` has a real value.
        ticket = TicketIdentity.objects().first().run_sync()
        assert ticket is not None

        ticket.name = "Back row"
        ticket.save().run_sync()

        self.assertEqual(
            TicketIdentity.select(TicketIdentity.name).run_sync(),
            [{"name": "Back row"}],
        )


@engines_only("sqlite")
class TestIdentityNonPrimaryKeySQLite(TestCase):
    def test_ddl(self):
        with self.assertRaises(ValueError) as manager:
            TicketIdentity.serial_number.ddl

        self.assertEqual(
            str(manager.exception),
            "`serial_number` - SQLite only supports identity columns for "
            "primary keys.",
        )


class TestTableMeta(TestCase):
    def test_read_only_columns(self):
        self.assertEqual(
            [i._meta.name for i in BandIdentity._meta.read_only_columns],
            ["id"],
        )
        # `GENERATED BY DEFAULT` columns can be written to.
        self.assertEqual(
            [i._meta.name for i in TicketIdentity._meta.read_only_columns],
            ["serial_number"],
        )

    def test_writable_columns(self):
        """
        Read only columns aren't writable, so are left out of inserts.
        """
        self.assertEqual(
            [i._meta.name for i in TicketIdentity._meta.writable_columns],
            ["id", "name", "ticket_number"],
        )
